)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if not private.is_platform_superadmin() then
    raise exception 'platform superadmin required' using errcode = '42501';
  end if;
  return query
  select
    tenant.id,
    tenant.display_name,
